import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h>

namespace cg = cooperative_groups;

#define BLOCK_THREADS 256

// Fused LayerNorm kernel.
// Each row (all elements in normalized_shape) is normalized independently.
// The row is split across several blocks for parallelism; a cooperative
// grid-wide sync separates the statistics pass from the normalize pass.
__global__ void layernorm_kernel(const float4* __restrict__ x,
                                 const float4* __restrict__ w,
                                 const float4* __restrict__ b,
                                 float4* __restrict__ y,
                                 double* __restrict__ stats,
                                 int nv, long n, float eps, int splits) {
    cg::grid_group grid = cg::this_grid();

    int row   = blockIdx.x / splits;
    int split = blockIdx.x - row * splits;
    long rowbase = (long)row * (long)nv;

    int chunk = (nv + splits - 1) / splits;
    int start = split * chunk;
    int end   = min(nv, start + chunk);

    // Pass 1: partial sums (double precision for accuracy).
    double s = 0.0, sq = 0.0;
    for (int i = start + threadIdx.x; i < end; i += BLOCK_THREADS) {
        float4 v = x[rowbase + i];
        s  += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
        sq += (double)v.x * v.x + (double)v.y * v.y +
              (double)v.z * v.z + (double)v.w * v.w;
    }

    const unsigned full_mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        s  += __shfl_down_sync(full_mask, s, offset);
        sq += __shfl_down_sync(full_mask, sq, offset);
    }
    __shared__ double ss[BLOCK_THREADS / 32];
    __shared__ double ssq[BLOCK_THREADS / 32];
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    if (lane == 0) {
        ss[warp]  = s;
        ssq[warp] = sq;
    }
    __syncthreads();
    if (warp == 0) {
        s  = (lane < (BLOCK_THREADS / 32)) ? ss[lane]  : 0.0;
        sq = (lane < (BLOCK_THREADS / 32)) ? ssq[lane] : 0.0;
        for (int offset = (BLOCK_THREADS / 32) / 2; offset > 0; offset >>= 1) {
            s  += __shfl_down_sync(full_mask, s, offset);
            sq += __shfl_down_sync(full_mask, sq, offset);
        }
        if (lane == 0) {
            atomicAdd(&stats[2 * row],     s);
            atomicAdd(&stats[2 * row + 1], sq);
        }
    }

    grid.sync();

    double mean = stats[2 * row] / (double)n;
    double var  = stats[2 * row + 1] / (double)n - mean * mean;
    double rstd = rsqrt(var + (double)eps);

    // Pass 2: normalize + affine transform.
    for (int i = start + threadIdx.x; i < end; i += BLOCK_THREADS) {
        float4 v  = x[rowbase + i];
        float4 wv = w[i];
        float4 bv = b[i];
        float4 o;
        o.x = (float)(((double)v.x - mean) * rstd) * wv.x + bv.x;
        o.y = (float)(((double)v.y - mean) * rstd) * wv.y + bv.y;
        o.z = (float)(((double)v.z - mean) * rstd) * wv.z + bv.z;
        o.w = (float)(((double)v.w - mean) * rstd) * wv.w + bv.w;
        y[rowbase + i] = o;
    }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w,
                                torch::Tensor b, double eps) {
    TORCH_CHECK(x.is_cuda() && x.scalar_type() == torch::kFloat32,
                "input must be a CUDA float tensor");
    auto xc = x.contiguous();
    auto wc = w.contiguous();
    auto bc = b.contiguous();
    auto y  = torch::empty_like(xc);

    long n    = wc.numel();
    long rows = xc.numel() / n;
    TORCH_CHECK(n % 4 == 0, "normalized size must be divisible by 4");
    int nv = (int)(n / 4);

    auto stats = torch::zeros({rows * 2},
                              xc.options().dtype(torch::kFloat64));

    int dev = 0;
    cudaGetDevice(&dev);
    int numSm = 0;
    cudaDeviceGetAttribute(&numSm, cudaDevAttrMultiProcessorCount, dev);
    int nbpm = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &nbpm, (void*)layernorm_kernel, BLOCK_THREADS, 0);
    long maxBlocks = (long)nbpm * (long)numSm;
    long splits = maxBlocks / rows;
    if (splits < 1)  splits = 1;
    if (splits > 32) splits = 32;

    dim3 gridDim((unsigned)(rows * splits));
    dim3 blockDim(BLOCK_THREADS);

    const float4* xp = reinterpret_cast<const float4*>(xc.data_ptr<float>());
    const float4* wp = reinterpret_cast<const float4*>(wc.data_ptr<float>());
    const float4* bp = reinterpret_cast<const float4*>(bc.data_ptr<float>());
    float4* yp       = reinterpret_cast<float4*>(y.data_ptr<float>());
    double* sp       = stats.data_ptr<double>();
    float epsf       = (float)eps;
    int splits_i     = (int)splits;

    void* args[] = { (void*)&xp, (void*)&wp, (void*)&bp, (void*)&yp,
                     (void*)&sp, (void*)&nv, (void*)&n,
                     (void*)&epsf, (void*)&splits_i };

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    cudaError_t err = cudaLaunchCooperativeKernel(
        (void*)layernorm_kernel, gridDim, blockDim, args, 0, stream);
    TORCH_CHECK(err == cudaSuccess, "cooperative launch failed: ",
                cudaGetErrorString(err));
    return y;
}
"""

cpp_src = ("torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w, "
           "torch::Tensor b, double eps);")

_mod = load_inline(
    name="layernorm_cuda_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    verbose=False,
    extra_cuda_cflags=["-O3"],
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a custom fused CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _mod.layernorm_forward(x, self.weight, self.bias, self.eps)

